test('leader announces itself; term-0 node joins without voting', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await deliverWhere(h, (m) => m.action === 'RequestVote' && m.to === 'n1');
  await deliverWhere(h, (m) => m.action === 'VoteReply');
