import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const NODES = ['n0', 'n1', 'n2'];

test('fresh system', async () => {
  const h = await createHost();
  for (const n of NODES) assert.deepEqual(await h.node(n), { role: 'follower', term: 0, votedFor: null, leader: null });
  assert.equal(await h.node('n3'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('timeout starts an election once', async () => {
  const h = await createHost();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'candidate', term: 1, votedFor: 'n0', leader: null });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  for (const m of msgs) {
    assert.equal(m.action, 'RequestVote');
    assert.equal(m.from, 'n0');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
  assert.equal((await h.timeout('n0')).ok, false);
  assert.equal((await h.timeout('x')).ok, false);
  assert.equal((await h.timeout('constructor')).ok, false);
});

test('single candidate wins', async () => {
  const h = await createHost();
  await h.timeout('n1');
  await h.deliverAll();
  assert.deepEqual(await h.node('n1'), { role: 'leader', term: 1, votedFor: 'n1', leader: 'n1' });
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n1', leader: 'n1' });
  assert.equal((await h.timeout('n0')).ok, false);
});

test('follower that voted refuses another candidate', async () => {
  const h = await createHost();
  await h.timeout('n0');
  const toN1 = (await h.inFlight()).find((m) => m.to === 'n1')!;
  await h.deliver(toN1.id);
  assert.equal((await h.timeout('n1')).ok, false);
  await h.timeout('n2');
  const rv = (await h.inFlight()).find((m) => m.from === 'n2' && m.to === 'n1')!;
  await h.deliver(rv.id);
  const reply = (await h.inFlight()).find((m) => m.from === 'n1' && m.to === 'n2')!;
  assert.deepEqual(reply.data, { term: 1, granted: false });
});

// Randomised exploration of timeouts and delivery orders.
test('safety under random schedules', async () => {
  let seed = 12345;
  const rnd = (n: number) => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed % n; };
  for (let run = 0; run < 3000; run++) {
    const h = await createHost();
    const voted = new Map<string, string>();
    for (let step = 0; step < 30; step++) {
      const msgs = await h.inFlight();
      const choice = rnd(msgs.length + 3);
      if (choice < 3) await h.timeout(NODES[choice]);
      else await h.deliver(msgs[choice - 3].id);
      const views = await Promise.all(NODES.map((n) => h.node(n)));
      const leaders = views.filter((v) => v!.role === 'leader');
      assert.ok(leaders.length <= 1);
      views.forEach((v, i) => {
        if (v!.votedFor !== null) {
          const prev = voted.get(NODES[i]);
          assert.ok(prev === undefined || prev === v!.votedFor, 'voted twice');
          voted.set(NODES[i], v!.votedFor);
        }
