          next.net = sorted([...net, `VR:${voter}>${candidate}:${granted ? 'T' : 'F'}`]);
          unchanged('votes', 'leader');
          return;
        }
        if (m.kind === 'LD') {
          const node = m.to;
          if (model.role[node] === 'leader') {
            // never happens with one leader per term; the message is consumed and ignored
            next.net = net;
            unchanged('role', 'term', 'votedFor', 'leader', 'votes');
            return;
          }
          next.role = { ...model.role, [node]: 'follower' };
          next.leader = { ...model.leader, [node]: m.from };
