//   'RV:<candidate>><voter>'           RequestVote { from: candidate, term: 1 }
//   'VR:<voter>><candidate>:<T|F>'     VoteReply   { term: 1, granted }
//   'LD:<leader>><node>'               Leader      { from: leader, term: 1 }
// Each message is sent at most once in the round, so the network is a sorted set.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const NODES = ['n0', 'n1', 'n2'];
const MAJORITY = 2;

const INITIAL_STATE = {
  role: { n0: 'follower', n1: 'follower', n2: 'follower' },
  term: { n0: 0, n1: 0, n2: 0 },
  votedFor: { n0: null, n1: null, n2: null },
  leader: { n0: null, n1: null, n2: null },
  votes: { n0: [], n1: [], n2: [] },
  net: [],
};

const ALL_MESSAGES = [];
for (const c of NODES) for (const v of NODES) if (c !== v) {
  ALL_MESSAGES.push(`RV:${c}>${v}`, `VR:${v}>${c}:T`, `VR:${v}>${c}:F`, `LD:${c}>${v}`);
}

const parse = (msg) => {
  const [kind, rest] = msg.split(':');
  const [from, to] = rest.split('>');
  return { kind, from, to, granted: msg.endsWith(':T') };
};

const sorted = (xs) => [...xs].sort();

const control = instance({
  initialState: JSON.parse(JSON.stringify(INITIAL_STATE)),
  component: {
    modelShape: {
      role: { type: 'object' },
      term: { type: 'object' },
      votedFor: { type: 'object' },
      leader: { type: 'object' },
      votes: { type: 'object' },
      net: { type: 'array' },
    },
    actions: {
      TIMEOUT: {
        action: (data = {}) => ({ ...data }),
        schema: { node: 'string' },
        domain: [{ node: 'n0' }, { node: 'n1' }, { node: 'n2' }, { node: 'n9' }],
      },
      DELIVER: {
        action: (data = {}) => ({ ...data }),
        schema: { msg: 'string' },
        domain: ALL_MESSAGES.map((msg) => ({ msg })),
      },
    },
    acceptors: {
      TIMEOUT: (model) => (proposal, { reject, next, unchanged }) => {
        const id = proposal.node;
        if (!NODES.includes(id)) return reject('unknown-node');
        if (model.role[id] !== 'follower' || model.term[id] !== 0) return reject('one-election-per-node');
        next.role = { ...model.role, [id]: 'candidate' };
        next.term = { ...model.term, [id]: 1 };
        next.votedFor = { ...model.votedFor, [id]: id };
        next.votes = { ...model.votes, [id]: [id] };
        next.net = sorted([...model.net, ...NODES.filter((o) => o !== id).map((o) => `RV:${id}>${o}`)]);
        unchanged('leader');
      },
      DELIVER: (model) => (proposal, { reject, next, unchanged }) => {
        const msg = proposal.msg;
        if (!model.net.includes(msg)) return reject('not-in-flight');
        const m = parse(msg);
        const net = model.net.filter((x) => x !== msg);
        if (m.kind === 'RV') {
          const voter = m.to;
          const candidate = m.from;
          let granted;
          if (model.term[voter] === 0) {
            next.term = { ...model.term, [voter]: 1 };
            next.role = { ...model.role, [voter]: 'follower' };
            next.votedFor = { ...model.votedFor, [voter]: candidate };
            granted = true;
          } else {
            granted = model.role[voter] === 'follower'
              && (model.votedFor[voter] === null || model.votedFor[voter] === candidate);
            if (granted) next.votedFor = { ...model.votedFor, [voter]: candidate };
            else unchanged('votedFor');
            unchanged('term', 'role');
          }
          next.net = sorted([...net, `VR:${voter}>${candidate}:${granted ? 'T' : 'F'}`]);
          unchanged('votes', 'leader');
          return;
        }
        if (m.kind === 'LD') {
          const node = m.to;
          if (model.role[node] === 'leader') {
            // never happens with one leader per term; the message is consumed and ignored
            next.net = net;
            unchanged('role', 'term', 'votedFor', 'leader', 'votes');
            return;
          }
          next.role = { ...model.role, [node]: 'follower' };
          next.leader = { ...model.leader, [node]: m.from };
          if (model.term[node] === 0) {
            next.term = { ...model.term, [node]: 1 };
            next.votedFor = { ...model.votedFor, [node]: null };
          } else {
            unchanged('term', 'votedFor');
          }
          next.net = net;
          unchanged('votes');
          return;
        }
        // VoteReply
        const candidate = m.to;
        unchanged('term', 'votedFor');
        if (model.role[candidate] === 'candidate' && model.term[candidate] === 1 && m.granted) {
          const votes = sorted(new Set([...model.votes[candidate], m.from]));
          next.votes = { ...model.votes, [candidate]: votes };
          if (votes.length >= MAJORITY) {
            next.role = { ...model.role, [candidate]: 'leader' };
            next.leader = { ...model.leader, [candidate]: candidate };
            next.net = sorted([...net, ...NODES.filter((o) => o !== candidate).map((o) => `LD:${candidate}>${o}`)]);
          } else {
            next.net = net;
            unchanged('role', 'leader');
          }
        } else {
          next.net = net;
          unchanged('role', 'votes', 'leader');
        }
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(JSON.parse(JSON.stringify(INITIAL_STATE))); };

const actions = {
  TIMEOUT: (data = {}) => intents.TIMEOUT(data),
  DELIVER: (data = {}) => intents.DELIVER(data),
};

module.exports = { instance, init, actions, getState, setState };

