test('safety under random schedules', async () => {
  let seed = 12345;
  const rnd = (n: number) => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed % n; };
  for (let run = 0; run < 3000; run++) {
    const h = await createHost();
    const voted = new Map<string, string>();
    for (let step = 0; step < 30; step++) {
      const msgs = await h.inFlight();
      const choice = rnd(msgs.length + 3);
      if (choice < 3) await h.timeout(NODES[choice]);
      else await h.deliver(msgs[choice - 3].id);
      const views = await Promise.all(NODES.map((n) => h.node(n)));
      const leaders = views.filter((v) => v!.role === 'leader');
      assert.ok(leaders.length <= 1);
      views.forEach((v, i) => {
        if (v!.votedFor !== null) {
          const prev = voted.get(NODES[i]);
          assert.ok(prev === undefined || prev === v!.votedFor, 'voted twice');
          voted.set(NODES[i], v!.votedFor);
        }
      });
      const leader = leaders.length ? NODES[views.indexOf(leaders[0])] : null;
      for (const v of views) assert.ok(v!.leader === null || v!.leader === leader, 'knows a non-leader as leader');
      for (const [i, v] of views.entries()) {
        if (v!.role === 'leader') {
          const supporters = views.filter((w) => w!.votedFor === NODES[i]).length;
          assert.ok(supporters >= 2);
