  initialState: JSON.parse(JSON.stringify(INITIAL_STATE)),
  component: {
    modelShape: {
      role: { type: 'object' },
      term: { type: 'object' },
      votedFor: { type: 'object' },
      leader: { type: 'object' },
      votes: { type: 'object' },
      net: { type: 'array' },
    },
