import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const NODES = ['n0', 'n1', 'n2'];

test('fresh system', async () => {
  const h = await createHost();
  for (const n of NODES) assert.deepEqual(await h.node(n), { role: 'follower', term: 0, votedFor: null, leader: null });
  assert.equal(await h.node('n3'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('timeout starts an election once', async () => {
  const h = await createHost();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'candidate', term: 1, votedFor: 'n0', leader: null });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  for (const m of msgs) {
    assert.equal(m.action, 'RequestVote');
    assert.equal(m.from, 'n0');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
  assert.equal((await h.timeout('n0')).ok, false);
  assert.equal((await h.timeout('x')).ok, false);
  assert.equal((await h.timeout('constructor')).ok, false);
});

test('single candidate wins', async () => {
  const h = await createHost();
  await h.timeout('n1');
  await h.deliverAll();
  assert.deepEqual(await h.node('n1'), { role: 'leader', term: 1, votedFor: 'n1', leader: 'n1' });
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n1', leader: 'n1' });
  assert.equal((await h.timeout('n0')).ok, false);
});

test('follower that voted refuses another candidate', async () => {
  const h = await createHost();
  await h.timeout('n0');
  const toN1 = (await h.inFlight()).find((m) => m.to === 'n1')!;
  await h.deliver(toN1.id);
  assert.equal((await h.timeout('n1')).ok, false);
  await h.timeout('n2');
  const rv = (await h.inFlight()).find((m) => m.from === 'n2' && m.to === 'n1')!;
  await h.deliver(rv.id);
  const reply = (await h.inFlight()).find((m) => m.from === 'n1' && m.to === 'n2')!;
  assert.deepEqual(reply.data, { term: 1, granted: false });
});

const deliverWhere = async (h: Awaited<ReturnType<typeof createHost>>, p: (m: any) => boolean) => {
  const m = (await h.inFlight()).find(p);
  assert.ok(m, 'message not in flight');
  await h.deliver(m.id);
};

test('leader announces itself; term-0 node joins without voting', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await deliverWhere(h, (m) => m.action === 'RequestVote' && m.to === 'n1');
  await deliverWhere(h, (m) => m.action === 'VoteReply');
  assert.equal((await h.node('n0'))!.role, 'leader');
  const leaderMsgs = (await h.inFlight()).filter((m) => m.action === 'Leader');
  assert.deepEqual(leaderMsgs.map((m) => m.to).sort(), ['n1', 'n2']);
  for (const m of leaderMsgs) assert.deepEqual(m.data, { from: 'n0', term: 1 });
  await deliverWhere(h, (m) => m.action === 'Leader' && m.to === 'n2');
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: null, leader: 'n0' });
  assert.equal((await h.timeout('n2')).ok, false);
  // the stale RequestVote still finds n2 unvoted in term 1, and it grants
  await deliverWhere(h, (m) => m.action === 'RequestVote' && m.to === 'n2');
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
});

test('candidate steps down on Leader and keeps its vote', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n2');
  await deliverWhere(h, (m) => m.action === 'RequestVote' && m.from === 'n0' && m.to === 'n1');
  await deliverWhere(h, (m) => m.action === 'VoteReply' && m.to === 'n0');
  await deliverWhere(h, (m) => m.action === 'Leader' && m.to === 'n2');
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n2', leader: 'n0' });
  await h.deliverAll();
  const views = await Promise.all(NODES.map((n) => h.node(n)));
  assert.deepEqual(views.map((v) => v!.role), ['leader', 'follower', 'follower']);
  assert.deepEqual(views.map((v) => v!.leader), ['n0', 'n0', 'n0']);
});

test('giveUp: candidate becomes follower, keeps its vote, ignores replies', async () => {
  const h = await createHost();
  assert.equal((await h.giveUp('n0')).ok, false);
  assert.equal((await h.giveUp('n9')).ok, false);
  await h.timeout('n0');
  await deliverWhere(h, (m) => m.action === 'RequestVote' && m.to === 'n1');
  assert.deepEqual(await h.giveUp('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  assert.equal((await h.giveUp('n0')).ok, false);
  assert.equal((await h.timeout('n0')).ok, false);
  await deliverWhere(h, (m) => m.action === 'VoteReply' && m.to === 'n0');
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  // n2 runs and n0 refuses its vote
  await h.timeout('n2');
  await deliverWhere(h, (m) => m.action === 'RequestVote' && m.from === 'n2' && m.to === 'n0');
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply' && m.from === 'n0')!;
  assert.deepEqual(reply.data, { term: 1, granted: false });
  await h.deliverAll();
  for (const n of NODES) assert.notEqual((await h.node(n))!.role, 'leader');
});

test('giveUp refused for a leader', async () => {
  const h = await createHost();
  await h.timeout('n1');
  await h.deliverAll();
  assert.equal((await h.giveUp('n1')).ok, false);
  assert.equal((await h.node('n1'))!.role, 'leader');
});

