const NODES = ['n0', 'n1', 'n2'];
const MAJORITY = 2;

const leaders = (s) => NODES.filter((n) => s.role[n] === 'leader');
const supporters = (s, c) => NODES.filter((n) => s.votedFor[n] === c);

export const stateInvariants = [
  { name: 'at-most-one-leader', pred: (s) => leaders(s).length <= 1 },
  { name: 'leader-holds-majority-of-votes', pred: (s) => leaders(s).every((l) => supporters(s, l).length >= MAJORITY) },
  { name: 'counted-votes-were-cast', pred: (s) => NODES.every((c) => s.votes[c].every((v) => s.votedFor[v] === c)) },
  { name: 'leader-and-candidate-in-term-1', pred: (s) => NODES.every((n) => s.role[n] === 'follower' || s.term[n] === 1) },
  { name: 'candidate-votes-for-itself', pred: (s) => NODES.every((n) => s.role[n] === 'follower' || s.votedFor[n] === n) },
  { name: 'vote-implies-term-1', pred: (s) => NODES.every((n) => s.votedFor[n] === null || s.term[n] === 1) },
  { name: 'terms-are-0-or-1', pred: (s) => NODES.every((n) => s.term[n] === 0 || s.term[n] === 1) },
  { name: 'known-leader-is-the-leader', pred: (s) => NODES.every((n) => s.leader[n] === null || s.role[s.leader[n]] === 'leader') },
  { name: 'leader-knows-itself', pred: (s) => NODES.every((n) => s.role[n] !== 'leader' || s.leader[n] === n) },
  { name: 'only-followers-know-another-leader', pred: (s) => NODES.every((n) => s.leader[n] === null || s.leader[n] === n || s.role[n] === 'follower') },
  { name: 'known-leader-implies-term-1', pred: (s) => NODES.every((n) => s.leader[n] === null || s.term[n] === 1) },
  { name: 'leader-never-receives-Leader', pred: (s) => s.net.every((m) => !m.startsWith('LD:') || s.role[m.slice(3).split('>')[1]] !== 'leader') },
];

export const transitionInvariants = [
  {
    name: 'no-node-votes-twice',
    pred: (pre, _a, _d, post) => NODES.every((n) => pre.votedFor[n] === null || post.votedFor[n] === pre.votedFor[n]),
  },
  {
    name: 'term-never-decreases',
    pred: (pre, _a, _d, post) => NODES.every((n) => post.term[n] >= pre.term[n]),
  },
  {
    name: 'known-leader-never-changes',
    pred: (pre, _a, _d, post) => NODES.every((n) => pre.leader[n] === null || post.leader[n] === pre.leader[n]),
  },
  {
    name: 'a-follower-never-becomes-leader-directly',
    pred: (pre, _a, _d, post) => NODES.every((n) => pre.role[n] !== 'follower' || post.role[n] !== 'leader'),
  },
  {
    name: 'giving-up-keeps-term-and-self-vote',
    pred: (pre, a, d, post) => a !== 'GIVE_UP' || pre.role[d.node] !== 'candidate'
      || (post.role[d.node] === 'follower' && post.term[d.node] === pre.term[d.node] && post.votedFor[d.node] === d.node),
