input.command:
node -e "
const fs=require('fs');let s=fs.readFileSync('spec/election.cjs','utf8');
const a=\"next.votes = { ...model.votes, [id]: [] };\n        unchanged('term', 'votedFor', 'leader', 'net');\";
if(!s.includes(a))throw new Error('no match');
s=s.replace(a,\"next.votes = { ...model.votes, [id]: [] };\n        next.votedFor = { ...model.votedFor, [id]: null };\n        unchanged('term', 'leader', 'net');\");
s='// NEGATIVE CONTROL: election.cjs where a crash loses the node\\'s vote; check.mjs must report violations.\n'+s;
fs.writeFileSync('spec/negative-control.cjs',s)"
node tools/polygraph/scripts/check.mjs --spec spec/negative-control.cjs --contract spec/contract.json --invariants spec/invariants.mjs 2>&1 | grep -E "✗|states explored|no invariant"

